import test from 'node:test';
import assert from 'node:assert/strict';
import {imageKey,signWbi,selectAac,allowedCdn} from '../bilibili/audio.mjs';
test('WBI fixed vector, extension stripping and immutable inputs',()=>{
  const img='7cd084941338484aae1ad9425b84077c',sub='4932caff0ff746eab6f01bf08b70ac45';
  const params={foo:'114',bar:'514',baz:'1919810'};
  assert.equal(imageKey(`https://i0.hdslb.com/bfs/wbi/${sub}.png`),sub);
  // Independently checked with Python hashlib + urllib.parse, using mixin key
  // ea1db124af3c7062474693fa704f4ff8; this is not generated by signWbi in the test.
  assert.equal(signWbi(params,img,sub,1702204169),'bar=514&baz=1919810&foo=114&wts=1702204169&w_rid=6149fdadf571698ca7e6a567265cd0ee');
  assert.deepEqual(params,{foo:'114',bar:'514',baz:'1919810'});
  assert.ok(signWbi({key:"a!'()* b中"},img,sub,1).startsWith('key=a%20b%E4%B8%AD&wts=1&'));
  assert.throws(()=>imageKey('https://i0.hdslb.com/key.png'));
});
test('highest compatible AAC, no FLAC/Dolby/video fallback',()=>{
  const a=(bandwidth,codecs='mp4a.40.2')=>({bandwidth,codecs,mimeType:'audio/mp4',baseUrl:'https://upos.bilivideo.com/fixture'});
  assert.equal(selectAac({dash:{audio:[a(64000),a(192000),a(999999,'flac')]}}).bitrate,192000);
  assert.throws(()=>selectAac({dash:{audio:[a(999999,'ec-3')]},durl:[{url:'https://upos.bilivideo.com/video'}]}),/unsupported_media/);
  for(const url of ['http://upos.bilivideo.com/a','https://127.0.0.1/a','https://upos.bilivideo.com.evil.test/a','https://u:p@upos.bilivideo.com/a'])assert.equal(allowedCdn(url),false);
});
